import{_ as o,o as i,c,ag as t}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-09-22（生物医学）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/biomedicine/science-daily-2026-09-22.md","filePath":"topics/biomedicine/science-daily-2026-09-22.md"}'),s={name:"topics/biomedicine/science-daily-2026-09-22.md"};function a(n,e,r,l,d,u){return i(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="科学日报-·-2026-09-22-生物医学" tabindex="-1">科学日报 · 2026-09-22（生物医学） <a class="header-anchor" href="#科学日报-·-2026-09-22-生物医学" aria-label="Permalink to &quot;科学日报 · 2026-09-22（生物医学）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-22.md</code> — 第29期</p></blockquote><hr><h2 id="sorganellomics-用多细胞器结构读出组织里的细胞状态与代谢适应-science" tabindex="-1">sOrganellomics：用多细胞器结构读出组织里的细胞状态与代谢适应（Science） <a class="header-anchor" href="#sorganellomics-用多细胞器结构读出组织里的细胞状态与代谢适应-science" aria-label="Permalink to &quot;sOrganellomics：用多细胞器结构读出组织里的细胞状态与代谢适应（Science）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-22.md</code> ｜ DOI: 10.1126/science.ady6372</p></blockquote><ul><li>现有范式：靠<strong>转录组</strong>定义细胞状态，忽略<strong>细胞器结构</strong>——而细胞器形态是代谢与应激的关键指标。</li><li>方法：空间细胞器组学（sOrganellomics）= 自动分割 + 机器学习，从多细胞器特征分类并<strong>空间映射</strong>细胞状态。</li><li>结果：肝与胰腺中可区分主要细胞类群；在肝脏里，&quot;分区位置&quot;<strong>不能完全解释</strong>细胞器定义的肝细胞类别——肝细胞在经典分区内形成<strong>混居群落</strong>，支持更细的&quot;亚分区多样性&quot;模型；营养应激（禁食）重塑该组织方式。</li><li>活体证据：活体成像把禁食诱导的细胞器重塑与<strong>线粒体膜电位改变</strong>联系起来 ⇒ 多细胞器架构可作为组织适应的<strong>结构性读数</strong>。</li><li>洞察：与库内&quot;测量维度决定能看见什么&quot;同构——换一个测量通道（结构而非转录），就会看到原分类体系漏掉的层级。也接续 09-21 期 MIT 系的多器官成像方向（<code>2026-q3-breakthroughs.md</code> 的 WHOLISTIC 类似物：从&quot;哪类细胞&quot;走向&quot;这群细胞在做什么代谢&quot;）。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/biomedicine/index.md</code> ｜ 第29期 科学板块</p></blockquote><p>关键词：细胞器组学、sOrganellomics、细胞状态、空间组学、线粒体膜电位、代谢适应、肝分区、亚分区多样性、活体成像 关联：<code>topics/biomedicine/science-daily-2026-09-21.md</code>（另一条&quot;换维度换结论&quot;的生物学证据）、<code>topics/biomedicine/2026-q3-breakthroughs.md</code>（全身活体成像）、<code>topics/quantum-physics/</code>（测量通道决定可见极限）</p>',9)])])}const q=o(s,[["render",a]]);export{p as __pageData,q as default};
